begin;
set local request.jwt.claims='{"aal":"aal2"}';
select plan(76);
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000901','csv-staff@example.test'),('00000000-0000-4000-8000-000000000902','csv-brand@example.test');
update public.profiles set role='staff' where id='00000000-0000-4000-8000-000000000901';
insert into public.brands(id,name,legal_name) values('00000000-0000-4000-8000-000000000903','CSV brand % literal','CSV legal');
insert into public.brand_private(id,notes) values('00000000-0000-4000-8000-000000000903','Private CSV notes');
insert into public.customers(id,legal_name,trade_name,city,notes) values('00000000-0000-4000-8000-000000000904','CSV customer','CSV shop','Roma','Private customer notes');
insert into public.seasons(id,brand_id,code,name) values('00000000-0000-4000-8000-000000000905','00000000-0000-4000-8000-000000000903','CSV26','CSV season');
insert into public.products(id,brand_id,season_id,sku_base,name,wholesale_price_cents) values('00000000-0000-4000-8000-000000000906','00000000-0000-4000-8000-000000000903','00000000-0000-4000-8000-000000000905','CSV-A','CSV product',100),('00000000-0000-4000-8000-000000000907','00000000-0000-4000-8000-000000000903','00000000-0000-4000-8000-000000000905','CSV-B','CSV product',20);
insert into public.budgets(id,brand_id,amount_cents,period_start,period_end) values('00000000-0000-4000-8000-000000000908','00000000-0000-4000-8000-000000000903',12345,'2034-01-01','2034-02-01');
insert into public.customer_contacts(customer_id,name,email) values('00000000-0000-4000-8000-000000000904','Private contact','private@example.test');
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000901';
select is(jsonb_array_length(public.export_business_list('brands','CSV legal')->'rows'),1,'general search includes legal name');
select is(jsonb_array_length(public.export_business_list('customers','CSV shop')->'rows'),1,'general search includes trade name');
select is(public.export_business_list('customers','Roma',p_ids=>array['00000000-0000-4000-8000-000000000904']::uuid[])->'rows'->0->>'legal_name','CSV customer','general search includes city and selection');
select is(jsonb_array_length(public.export_business_list('customers','Private customer notes')->'rows'),0,'hidden notes cannot influence search');
select is(jsonb_array_length(public.export_business_list('brands','Private CSV notes')->'rows'),0,'hidden brand notes cannot influence search');
select is(public.export_business_list('seasons','CSV26')->'rows'->0->>'name','CSV season','general search includes season code');
select is(public.export_business_list('products','CSV-B')->'rows'->0->>'wholesale_price_cents','20','general search includes SKU');
select is(public.export_business_list('products','0,20')->'rows'->0->>'sku_base','CSV-B','general search includes formatted money');
select is(public.export_business_list('products','CSV brand % literal')->'rows'->0->>'name','CSV product','general search includes related brand');
select is(public.export_business_list('budgets','123,45')->'rows'->0->>'id','00000000-0000-4000-8000-000000000908','general search includes budget amount');
select is(public.export_business_list('budgets','Nessuno',p_ids=>array['00000000-0000-4000-8000-000000000908']::uuid[])->'rows'->0->>'id','00000000-0000-4000-8000-000000000908','general search includes displayed missing scope');
select matches(public.table_search(row(null,'2034-01-01 12:34:56+00','insert','brands',null,null)::public.v_audit_list),'Sistema','audit search includes displayed system author');
select matches(public.table_search(row(null,'2034-01-01 12:34:56+00','insert','brands',null,null)::public.v_audit_list),'01/01/34 13:34:56','audit search includes displayed short date and local time');
select is(public.table_filter_options('products','wholesale_price_cents','0,20'),'["20"]'::jsonb,'money combobox search accepts displayed decimal values');
select is(public.export_business_list('products','0,20'||chr(160)||'€')->'rows'->0->>'sku_base','CSV-B','copied formatted currency can be searched');
select is(public.table_filter_options('customers','city','Roma'),'["Roma"]'::jsonb,'combobox values are distinct RLS-visible choices');
select throws_ok($$select public.table_filter_options('customers','notes','')$$,'22023',null,'private filter choices rejected');
select throws_ok($$select public.table_filter_options('brands','name; select 1','')$$,'22023',null,'choice identifier injection refused');
select ok(not(public.export_business_list('products','CSV product')->'rows'->0 ? 'search_text'),'search field excluded from export payload');
select is(public.export_business_list('brands','% literal')->'rows'->0->>'name','CSV brand % literal','percent search is literal');
select is(jsonb_array_length(public.export_business_list('brands','no-matching-csv-brand')->'rows'),0,'empty export');
select ok(public.export_business_list('brands','CSV brand')::text not like '%Private CSV notes%','private brand fields excluded');
select is(public.export_business_list('customers','CSV customer')->'rows'->0->>'city','Roma','customer visible fields');
select ok(public.export_business_list('customers','CSV customer')::text not like '%private@example.test%' and public.export_business_list('customers','CSV customer')::text not like '%Private customer notes%','customer contacts and notes excluded');
select is(public.export_business_list('seasons','CSV season')->'rows'->0->>'brand','CSV brand % literal','season includes brand');
select is(public.export_business_list('products','CSV product','wholesale_price_cents')->'rows'->0->>'wholesale_price_cents','20','money sorted numerically');
select is(public.export_business_list('products','CSV product','wholesale_price_cents','desc')->'rows'->0->>'wholesale_price_cents','100','descending money');
select is(public.export_business_list('budgets','CSV brand')->'rows'->0->>'amount_cents','12345','budget cents serialized exactly');
select is(jsonb_array_length(public.export_business_list('products',p_ids=>array['00000000-0000-4000-8000-000000000907']::uuid[])->'rows'),1,'selection restricts export');
select is(jsonb_array_length(public.export_business_list('products','no-match',p_ids=>array['00000000-0000-4000-8000-000000000907']::uuid[])->'rows'),0,'selection also honors search');
select is(jsonb_array_length(public.export_business_list('products',p_ids=>'{}'::uuid[])->'rows'),0,'empty RPC selection does not export all');
select is(jsonb_array_length(public.export_business_list('products',p_ids=>array['00000000-0000-4000-8000-000000000907']::uuid[],p_column_filters=>'{"wholesale_price_cents":"100"}')->'rows'),0,'selection intersects column filter');
select is(public.export_business_list('products',p_column_filters=>'{"wholesale_price_cents":"20"}')->'rows'->0->>'sku_base','CSV-B','money equality uses cents');
select is(jsonb_array_length(public.export_business_list('brands',p_column_filters=>'{"name":"% literal","legal_name":"csv LEGAL"}')->'rows'),1,'literal text filters combine case-insensitively');
select is(jsonb_array_length(public.export_business_list('customers',p_column_filters=>'{"city":"Roma","trade_name":"nonmatching"}')->'rows'),0,'all text filters must match');
select is(public.export_business_list('budgets',p_column_filters=>'{"amount_cents":"12345","period_start":"2034-01-01"}')->'rows'->0->>'id','00000000-0000-4000-8000-000000000908','date and money filters combine');
select throws_ok($$select public.export_business_list('brands',p_ids=>array_fill('00000000-0000-4000-8000-000000000903'::uuid,array[501]))$$,'22023',null,'oversized selection rejected');
select throws_ok($$select public.export_business_list('brands',p_ids=>array[null]::uuid[])$$,'22023',null,'null IDs rejected');
select throws_ok($$select public.export_business_list('customers',p_column_filters=>'{"notes":"Private"}')$$,'22023',null,'private columns cannot filter');
select throws_ok($$select public.export_business_list('brands',p_column_filters=>'{"name; drop table brands":"x"}')$$,'22023',null,'column injection rejected');
select throws_ok($$select public.export_business_list('products',p_column_filters=>'{"wholesale_price_cents":"1.5"}')$$,'22023',null,'fractional cents rejected');
select throws_ok($$select public.export_business_list('products',p_column_filters=>'{"wholesale_price_cents":"1000000000001"}')$$,'22023',null,'oversized amount rejected');
select throws_ok($$select public.export_business_list('documents',p_column_filters=>'{"size_bytes":"10485761"}')$$,'22023',null,'oversized size rejected');
select throws_ok($$select public.export_business_list('customers',p_column_filters=>'{"city":null}')$$,'22023',null,'nonstring filter rejected');
select lives_ok($$select public.export_business_list('documents')$$,'document export');
select lives_ok($$select public.export_business_list('invoices','','due_date','asc','paid',true)$$,'invoice filters');
select throws_ok($$select public.export_business_list('audit_log')$$,'22023',null,'private relation cannot be exported');
select throws_ok($$select public.export_business_list('brands','','name; drop table brands')$$,'22023',null,'sort injection rejected');
select throws_ok($$select public.export_business_list('brands','','name','asc; select 1')$$,'22023',null,'direction injection rejected');
select throws_ok($$select public.export_business_list('invoices','','number','asc','invalid')$$,'22023',null,'invalid invoice status rejected');
select lives_ok($$select public.export_business_list('seasons',p_sort=>'brand',p_direction=>'desc')$$,'seasons.brand sorts in export');
select lives_ok($$select public.export_business_list('products',p_sort=>'brand',p_direction=>'desc')$$,'products.brand sorts in export');
select lives_ok($$select public.export_business_list('products',p_sort=>'season',p_direction=>'desc')$$,'products.season sorts in export');
select lives_ok($$select public.export_business_list('budgets',p_sort=>'brand',p_direction=>'desc')$$,'budgets.brand sorts in export');
select lives_ok($$select public.export_business_list('budgets',p_sort=>'season',p_direction=>'desc')$$,'budgets.season sorts in export');
select lives_ok($$select public.export_business_list('budgets',p_sort=>'customer',p_direction=>'desc')$$,'budgets.customer sorts in export');
select lives_ok($$select public.export_business_list('budgets',p_sort=>'period_end',p_direction=>'desc')$$,'budgets.period_end sorts in export');
select lives_ok($$select public.export_business_list('documents',p_sort=>'brand',p_direction=>'desc')$$,'documents.brand sorts in export');
select lives_ok($$select public.export_business_list('documents',p_sort=>'kind',p_direction=>'desc')$$,'documents.kind sorts in export');
select lives_ok($$select public.export_business_list('documents',p_sort=>'shared_with_brand',p_direction=>'desc')$$,'documents.shared_with_brand sorts in export');
select lives_ok($$select public.export_business_list('documents',p_sort=>'size_bytes',p_direction=>'desc')$$,'documents.size_bytes sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'brand',p_direction=>'desc')$$,'invoices.brand sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'customer',p_direction=>'desc')$$,'invoices.customer sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'status',p_direction=>'desc')$$,'invoices.status sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'gross_cents',p_direction=>'desc')$$,'invoices.gross_cents sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'paid_cents',p_direction=>'desc')$$,'invoices.paid_cents sorts in export');
select lives_ok($$select public.export_business_list('invoices',p_sort=>'balance_cents',p_direction=>'desc')$$,'invoices.balance_cents sorts in export');
select is((select count(*) from public.v_audit_list),0::bigint,'staff cannot read audit through sorted view');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.v_audit_list'::regclass),'audit names view applies caller RLS');
set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000902';
select throws_ok($$select public.export_business_list('brands')$$,'42501',null,'brand cannot call internal export directly');
reset role;
update public.profiles set role='accounting' where id='00000000-0000-4000-8000-000000000901';
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000000901';
select lives_ok($$select public.export_business_list('customers','CSV')$$,'accounting may export readable data');
reset role;
update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000000901';
set local role authenticated;set local request.jwt.claims='{"aal":"aal1"}';
select throws_ok($$select public.export_business_list('customers')$$,'42501',null,'password-only admin refused');
set local request.jwt.claims='{"aal":"aal2"}';
select lives_ok($$select public.export_business_list('brands')$$,'MFA admin allowed');
reset role;
select ok(not has_function_privilege('anon','public.export_business_list(text,text,text,text,text,boolean,uuid[],jsonb,uuid)','execute'),'anonymous RPC denied');
select ok(not (select prosecdef from pg_proc where oid='public.export_business_list(text,text,text,text,text,boolean,uuid[],jsonb,uuid)'::regprocedure),'export preserves session RLS');
insert into public.customers(legal_name) select 'CSV capacity unique '||n from generate_series(1,10002) n;
set local role authenticated;
select is(jsonb_array_length(public.export_business_list('customers','CSV capacity unique')->'rows'),10001,'bounded response signals overflow instead of silently truncating');
select * from finish();rollback;
